// The per-part geometry file the 3D scene is built from (schema 2, generated by the PC catalog's
// owner from catalog data). This module only reads and checks it; it draws nothing.
//
// Frame of a part: right-handed, +y up, millimetres, origin at the minimum corner of `bounds`.
// A solid's `at` is its centre. A cylinder's `height` runs along `axis`.

/** Schema 1 gave a solid's minimum corner; schema 2 gives its centre. Only 2 is read. */
export const GEOMETRY_SCHEMA = 2;

export type Vec3 = readonly [number, number, number];
/** x, y, z, w. */
export type Quat = readonly [number, number, number, number];
export type Basis = "catalog" | "standard" | "schematic";

/** A position and an orientation in a part's own frame. */
export interface Frame {
  at: Vec3;
  quat: Quat;
}

export interface Solid {
  id: string;
  /** Shapes this reader does not know are skipped, so a later generator can add some. */
  shape: string;
  at: Vec3;
  size?: Vec3;
  radius?: number;
  height?: number;
  axis?: "x" | "y" | "z";
  rotation?: Quat;
  /** For a part made of separately mounted bodies (a liquid cooler's block and radiator): the mounting role this solid moves with. */
  group?: string;
  /** A printed marking such as `CPU_FAN` or `DIMM_A2`; language-neutral. */
  label?: string;
  /** What the solid is (pcb, heatsink, fan, slot, port, shroud…), for the choice of material. */
  role: string;
  /** Plates of a `fins` solid, blades of a `rotor`. */
  count?: number;
  /** A generic surface (circuit board, gold, anodised metal, plastic, glass…); absent means the role decides. */
  finish?: string;
  basis: Basis;
}

export interface MountGeometry extends Frame {
  /** Unit vector in this (the host's) frame: the direction a part travels to seat. */
  insert: Vec3;
  /** How far back along `insert` a part sits while it is only placed. */
  travelMm: number;
  solid: string;
  /** Extent of the position, centred on `at`. */
  size?: Vec3;
  /** Unit vector toward a viewer who can see the position; used to turn the camera to it. */
  facing?: Vec3;
}

export interface PortGeometry {
  at: Vec3;
  /** Unit vector: the direction a cable leaves the port. */
  facing: Vec3;
  size?: Vec3;
  solid: string;
}

export interface PartGeometry {
  schema: 2;
  catalogId: string;
  catalogVersion: string;
  units: "mm";
  bounds: { size: Vec3; basis: { x: Basis; y: Basis; z: Basis } };
  solids: Solid[];
  /** Where this part meets its host, by mounting role. */
  attach: Record<string, Frame>;
  /** Where other parts go on this one, by mount point ID. */
  mounts: Record<string, MountGeometry>;
  ports: Record<string, PortGeometry>;
  /** Where a fixed lead leaves the part, by cable spec ID. */
  leads: Record<string, { at: Vec3 }>;
  zones: Record<string, { solids: string[] }>;
  /** Present only when the catalog entry has lighting hardware. */
  lights: { zone: string; solids: string[] }[];
  clearance?: { kind: string; at: Vec3; size: Vec3 }[];
  /** Shown in the scene: the model is educational, not manufacturer-accurate. */
  label: { en: string; ar: string };
}

function isObject(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

const isNumbers = (value: unknown, length: number): boolean =>
  Array.isArray(value) && value.length === length && value.every((item) => typeof item === "number" && Number.isFinite(item));
const isVec3 = (value: unknown): value is Vec3 => isNumbers(value, 3);
const isQuat = (value: unknown): value is Quat => isNumbers(value, 4);
const isFrame = (value: unknown): boolean => isObject(value) && isVec3(value.at) && isQuat(value.quat);

export type GeometryProblem = "not_object" | "unsupported_schema" | "wrong_part" | "bad_bounds" | "bad_solid" | "bad_frame" | "bad_port" | "dangling_reference";

export type ParsedGeometry = { ok: true; geometry: PartGeometry } | { ok: false; problem: GeometryProblem; detail?: string };

const fail = (problem: GeometryProblem, detail?: string): ParsedGeometry => ({ ok: false, problem, detail });

/**
 * Checks a geometry file before anything is drawn from it: the right schema and part, finite
 * numbers, drawable sizes, and every reference (mount, port, zone, light) naming a solid that
 * exists. A file that fails is not drawn; the part falls back to the labelled "no model yet" box.
 */
export function parseGeometry(raw: unknown, catalogId: string): ParsedGeometry {
  if (!isObject(raw)) return fail("not_object");
  if (raw.schema !== GEOMETRY_SCHEMA || raw.units !== "mm") return fail("unsupported_schema");
  if (raw.catalogId !== catalogId) return fail("wrong_part", String(raw.catalogId));
  if (!isObject(raw.bounds) || !isVec3(raw.bounds.size) || raw.bounds.size.some((side) => side <= 0)) return fail("bad_bounds");
  if (!Array.isArray(raw.solids) || raw.solids.length === 0) return fail("bad_solid", "none");

  const ids = new Set<string>();
  for (const solid of raw.solids) {
    if (!isObject(solid) || typeof solid.id !== "string" || typeof solid.shape !== "string" || typeof solid.role !== "string" || !isVec3(solid.at)) {
      return fail("bad_solid", isObject(solid) ? String(solid.id) : undefined);
    }
    if (ids.has(solid.id)) return fail("bad_solid", `duplicate ${solid.id}`);
    if (solid.rotation !== undefined && !isQuat(solid.rotation)) return fail("bad_solid", solid.id);
    if ((solid.shape === "box" || solid.shape === "fins") && (!isVec3(solid.size) || solid.size.some((side) => side <= 0))) return fail("bad_solid", solid.id);
    if ((solid.shape === "fins" || solid.shape === "rotor") && (typeof solid.count !== "number" || !Number.isInteger(solid.count) || solid.count < 1)) return fail("bad_solid", solid.id);
    if (solid.shape === "fins" && solid.axis !== "x" && solid.axis !== "y" && solid.axis !== "z") return fail("bad_solid", solid.id);
    if (solid.finish !== undefined && typeof solid.finish !== "string") return fail("bad_solid", solid.id);
    if (solid.shape === "cylinder" || solid.shape === "rotor") {
      const sized = typeof solid.radius === "number" && solid.radius > 0 && typeof solid.height === "number" && solid.height > 0;
      if (!sized || (solid.axis !== "x" && solid.axis !== "y" && solid.axis !== "z")) return fail("bad_solid", solid.id);
    }
    ids.add(solid.id);
  }

  const names = (list: unknown) => Array.isArray(list) && list.every((id) => typeof id === "string" && ids.has(id));
  if (!isObject(raw.attach) || !Object.values(raw.attach).every(isFrame)) return fail("bad_frame", "attach");
  if (!isObject(raw.mounts)) return fail("bad_frame", "mounts");
  for (const [id, mount] of Object.entries(raw.mounts)) {
    if (!isObject(mount) || !isFrame(mount) || !isVec3(mount.insert) || typeof mount.travelMm !== "number") return fail("bad_frame", `mount ${id}`);
    if (!ids.has(String(mount.solid))) return fail("dangling_reference", `mount ${id}`);
  }
  if (!isObject(raw.ports)) return fail("bad_port");
  for (const [id, port] of Object.entries(raw.ports)) {
    if (!isObject(port) || !isVec3(port.at) || !isVec3(port.facing)) return fail("bad_port", id);
    if (!ids.has(String(port.solid))) return fail("dangling_reference", `port ${id}`);
  }
  if (!isObject(raw.zones) || !Object.values(raw.zones).every((zone) => isObject(zone) && names(zone.solids))) return fail("dangling_reference", "zones");
  if (!Array.isArray(raw.lights) || !raw.lights.every((light) => isObject(light) && typeof light.zone === "string" && names(light.solids))) {
    return fail("dangling_reference", "lights");
  }
  if (raw.leads !== undefined && (!isObject(raw.leads) || !Object.values(raw.leads).every((lead) => isObject(lead) && isVec3(lead.at)))) {
    return fail("bad_frame", "leads");
  }
  if (!isObject(raw.label) || typeof raw.label.en !== "string" || typeof raw.label.ar !== "string") return fail("not_object", "label");
  return { ok: true, geometry: { ...(raw as unknown as PartGeometry), leads: (raw.leads ?? {}) as PartGeometry["leads"] } };
}
